<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$viewer=current_user($pdo);$id=(string)($_GET['id']??'');$from=(int)($_GET['from']??0);$to=(int)($_GET['to']??0);$source=source_access($pdo,$id,$viewer);if(!$source){http_response_code(404);exit('Source not found.');}$q=$pdo->prepare('SELECT id,version_number,captured_at,extracted_text FROM source_versions WHERE source_id=? AND id IN (?,?)');$q->execute([$source['id'],$from,$to]);$rows=[];foreach($q->fetchAll() as $r)$rows[(int)$r['id']]=$r;if(!isset($rows[$from],$rows[$to]))exit('Version not found.');$diff=simple_text_diff((string)$rows[$from]['extracted_text'],(string)$rows[$to]['extracted_text']);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Compare source versions · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/">Annotated</a><nav><a href="/source.php?id=<?=h($id)?>">Back to source</a></nav></header><main class="panel article"><span class="eyebrow">SOURCE COMPARISON</span><h1><?=h($source['title']?:$source['canonical_url'])?></h1><p class="meta">Version <?=h((string)$rows[$from]['version_number'])?> · <?=h($rows[$from]['captured_at'])?> → Version <?=h((string)$rows[$to]['version_number'])?> · <?=h($rows[$to]['captured_at'])?></p><div class="diff"><?php foreach($diff as $line):?><div class="diffLine <?=h($line['type'])?>"><span><?= $line['type']==='added'?'+':($line['type']==='removed'?'-':' ') ?></span><pre><?=h($line['text'])?></pre></div><?php endforeach?></div></main></body></html>